findings.after:
// Assert the surface IS its token, the way the ghost-hover and engine-error shots already do.
const expectBackgroundEquals = async (page: Page, testId: string, css: string): Promise<void> => {
  const expected = await page.evaluate((expression) => {
    const probe = document.createElement('div');
    probe.style.backgroundColor = expression;
    document.body.append(probe);
    const value = globalThis.getComputedStyle(probe).backgroundColor;
    probe.remove();
    return value;
  }, css);
  // A deleted token makes var() invalid at computed-value time, which would make this vacuous.
  expect(expected).not.toBe('rgba(0, 0, 0, 0)');
  await expect
    .poll(() => page.getByTestId(testId).evaluate((el) => globalThis.getComputedStyle(el).backgroundColor))
    .toBe(expected);
};
